@@ -8,24 +8,37 @@ export function validarNit(nit) {
 }

 // RF-002: el IVA va incluido en el precio; se informa, no se suma.
-export function calcularFactura(items) {
+// RF-006: descuento global opcional (porcentaje entero 0-100) sobre el total de las líneas; el IVA y el neto
+// se calculan sobre el total ya descontado.
+export function calcularFactura(items, { descuentoGlobalPorcentaje } = {}) {
   if (!Array.isArray(items) || items.length === 0) throw new Error("Una factura necesita al menos una línea");
-  let totalCentavos = 0;
+  const conDescuento = descuentoGlobalPorcentaje !== undefined;
+  if (
+    conDescuento &&
+    (!Number.isInteger(descuentoGlobalPorcentaje) || descuentoGlobalPorcentaje < 0 || descuentoGlobalPorcentaje > 100)
+  )
+    throw new RangeError("Descuento global inválido: debe ser un porcentaje entero de 0 a 100");
+  let subtotalCentavos = 0;
   for (const item of items) {
     if (!Number.isInteger(item.cantidad) || item.cantidad <= 0) throw new RangeError("Cantidad inválida");
     if (!Number.isInteger(item.precioUnitarioCentavos) || item.precioUnitarioCentavos < 0)
       throw new RangeError("Precio inválido: debe estar en centavos enteros");
-    totalCentavos += item.cantidad * item.precioUnitarioCentavos;
+    subtotalCentavos += item.cantidad * item.precioUnitarioCentavos;
   }
+  const descuentoGlobalCentavos = conDescuento ? Math.round((subtotalCentavos * descuentoGlobalPorcentaje) / 100) : 0;
+  const totalCentavos = subtotalCentavos - descuentoGlobalCentavos;
   const ivaCentavos = Math.round(totalCentavos * TASA_IVA);
-  return { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
+  const base = { totalCentavos, ivaCentavos, netoCentavos: totalCentavos - ivaCentavos };
+  return conDescuento ? { subtotalCentavos, descuentoGlobalCentavos, ...base } : base;
 }

 // RF-001, RF-003: emite una factura válida y congelada.
-export function emitirFactura({ numero, nit, razonSocial, items }) {
+export function emitirFactura({ numero, nit, razonSocial, items, descuentoGlobalPorcentaje }) {
   if (!validarNit(nit)) throw new Error("NIT inválido");
+  const calculo = calcularFactura(items, { descuentoGlobalPorcentaje });
   const lineas = Object.freeze(items.map((item) => Object.freeze({ ...item })));
-  return Object.freeze({ numero, nit, razonSocial, items: lineas, ...calcularFactura(items), estado: "emitida" });
+  const descuento = descuentoGlobalPorcentaje === undefined ? {} : { descuentoGlobalPorcentaje };
+  return Object.freeze({ numero, nit, razonSocial, items: lineas, ...descuento, ...calculo, estado: "emitida" });
 }

